@sig trait Release_Command_Derivation_Api {
  def id: Art.BridgeId
  def dispatch_resolution_Id : Art.PortId
  def shipment_release_command_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var shipment_release_command: Factory_Dispatch_Coordinator.Shipment_Release_Command.Type = $

  def put_shipment_release_command(value : Factory_Dispatch_Coordinator.Shipment_Release_Command.Type) : Unit = {
    Contract(
      Modifies(shipment_release_command),
      Ensures(
        shipment_release_command == value
      )
    )
    Spec {
      shipment_release_command = value
    }

    Art.putValue(shipment_release_command_Id, Factory_Dispatch_Coordinator.Shipment_Release_Command_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Release_Command_Derivation_Initialization_Api (
  val id: Art.BridgeId,
  val dispatch_resolution_Id : Art.PortId,
  val shipment_release_command_Id : Art.PortId) extends Release_Command_Derivation_Api

@datatype class Release_Command_Derivation_Operational_Api (
  val id: Art.BridgeId,
  val dispatch_resolution_Id : Art.PortId,
  val shipment_release_command_Id : Art.PortId) extends Release_Command_Derivation_Api {

  // Logika spec var representing port state for incoming data port
  @spec var dispatch_resolution: Factory_Dispatch_Coordinator.Dispatch_Resolution = $

  def get_dispatch_resolution() : Option[Factory_Dispatch_Coordinator.Dispatch_Resolution] = {
    Contract(
      Ensures(
        Res == Some(dispatch_resolution)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Dispatch_Resolution] = Art.getValue(dispatch_resolution_Id) match {
      case Some(Factory_Dispatch_Coordinator.Dispatch_Resolution_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port dispatch_resolution.  Expecting 'Factory_Dispatch_Coordinator.Dispatch_Resolution_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Dispatch_Resolution]()
      case _ => None[Factory_Dispatch_Coordinator.Dispatch_Resolution]()
    }
    return value
  }
}
